// Üretilen dosya: tool/ozgun/uret.py. Coğrafya · Ekonomik coğrafya: tarım, madenler, enerji kaynakları, ticaret yolları (dünya) (kolay).
const ozGeography9Kolay = <(String, String, List<String>, String)>[
  ('Birim alana az emek, sermaye ve girdi kullanılarak geniş alanlarda yapılan, bu nedenle hektar başına verimi düşük olan tarım türüne ne ad verilir?', 'Ekstansif tarım', ['Entansif (yoğun girdili) tarım', 'Seracılık', 'Bahçe tarımı'], 'Ekstansif tarımda geniş araziye karşın girdi az kullanılır; toplam üretim yüksek olabilse de birim alandan alınan verim düşüktür.'),
  ('Sulama, gübre, ilaç, makine ve tohum ıslahının yoğun kullanılmasıyla birim alandan yüksek verim alınan tarım yöntemi hangisidir?', 'Entansif tarım', ['Ekstansif tarım', 'Kes-yak tarımı', 'Nadas tarımı'], 'Entansif (yoğun) tarım, birim alana çok girdi uygulayarak verimi artırmayı hedefler; Hollanda ve Japonya tipik örneklerdir.'),
  ('Bir köylü ailesinin ürettiği ürünlerin neredeyse tamamını kendi tüketimi için kullandığı, pazara çok az ürün sattığı tarım türü hangisidir?', 'Geçimlik tarım', ['Ticari tarım', 'Plantasyon tarımı', 'Sözleşmeli tarım'], 'Geçimlik (kendine yeterli) tarımda amaç pazar değil ailenin beslenmesidir; ürün çeşitliliği yüksek, pazara ayrılan pay düşüktür.'),
  ('Aşağıdaki tarımsal etkinliklerden hangisi geçimlik değil, ticari tarıma örnektir?', 'Brezilya\'da ihracat için soya yetiştirilmesi', ['Yağmur ormanında ailenin manyok ekmesi', 'Dağ köyünde aile için arpa ekilmesi', 'Sahel\'de ailenin darı yetiştirmesi'], 'Ticari tarımda üretim pazara, özellikle ihracata yöneliktir; Brezilya soyası büyük ölçüde dış pazara satılır.'),
  ('Büyük kentlerin çevresinde, kente taze sebze, meyve ve süt sağlamak amacıyla yapılan yoğun tarıma ne ad verilir?', 'Pazar bahçeciliği', ['Göçebe hayvancılık', 'Plantasyon tarımı', 'Ekstansif tahıl tarımı'], 'Bozulabilir ürünlerin pazara hızla ulaşması gerektiği için kent çevrelerinde yoğun bahçe ve süt tarımı gelişir.'),
  ('Tropikal bölgelerde genellikle yabancı sermayeyle kurulan, tek bir ihraç ürünü yetiştiren büyük çiftliklere ne ad verilir?', 'Plantasyon', ['Hacienda', 'Kolhoz', 'Ranch'], 'Plantasyonlar sömürge döneminde yaygınlaşmış, kahve, çay, kauçuk, şeker kamışı gibi tek ürüne odaklanan büyük tarım işletmeleridir.'),
  ('Plantasyon tarımının tipik özellikleri arasında aşağıdakilerden hangisi yer almaz?', 'Ürünün büyük kısmının çiftçi ailesince tüketilmesi', ['Tek bir ürüne odaklanılması', 'Bol ve ucuz işgücünün yoğun olarak kullanılması', 'Ürünün ihracata yönelik olması'], 'Plantasyonlar ticari ve ihracat odaklıdır; ürünün aile tüketimine ayrılması geçimlik tarımın özelliğidir.'),
  ('Plantasyonların genellikle kıyıya ya da bir limana yakın kurulmasının temel nedeni nedir?', 'Ürünün dış pazarlara gemiyle kolayca gönderilebilmesi', ['Kıyıda tropikal yağışın hiç görülmemesi', 'İç kesimlerde işçi olarak çalışacak nüfusun hiç bulunmaması', 'Tuzlu toprağın bu ürünlere yaraması'], 'Plantasyon ürünleri ağırlıkla ihraç edildiğinden limana yakınlık taşıma maliyetini ve süresini azaltır.'),
  ('ABD\'nin Büyük Ovaları ve Arjantin\'deki geniş çitli arazilerde büyükbaş hayvanların ticari amaçla otlatıldığı büyük çiftliklere ne ad verilir?', 'Ranch', ['Plantasyon', 'Kibbutz', 'Oba'], 'Ranch, geniş otlaklarda et üretimi için yapılan ekstansif ve ticari büyükbaş hayvancılık işletmesidir.'),
  ('Moğolistan bozkırlarında geleneksel hayvancılığın sürekli yer değiştirilerek yapılmasının temel nedeni nedir?', 'Kurak bozkırda otun kısa sürede tükenmesi', ['Kışın otların daha hızlı büyümesi', 'Hayvanların yalnız ormanlarda otlayabilmesi', 'Sabit köylerin yasalarla yasaklanmış olması'], 'Az yağışlı bozkırlarda bir alanın otu sürüyü uzun süre besleyemez; sürüler yeni otlaklara taşınarak meranın yenilenmesi sağlanır.'),
  ('Laponya\'da (Kuzey İskandinavya) Saami halkının geleneksel hayvancılığı hangi hayvana dayanır?', 'Ren geyiği', ['Lama', 'Yak', 'Deve'], 'Saamiler ren geyiği sürülerini tundra ile tayga arasında mevsimlik olarak güderek et, deri ve süt elde eder.'),
  ('İnce ve kaliteli yünüyle tanınan, kökeni İspanya\'ya dayanan ve Avustralya\'nın yün ihracatının temelini oluşturan koyun ırkı hangisidir?', 'Merinos', ['Karaman', 'Akkaraman', 'İvesi'], 'Merinos koyunu İspanya\'da gelişmiş, 18-19. yüzyıllarda Avustralya\'ya götürülmüş ve ülkeyi dünyanın başlıca ince yün üreticisi yapmıştır.'),
  ('And Dağları\'nda yünü için yetiştirilen ve lamanın akrabası olan evcil hayvan hangisidir?', 'Alpaka', ['Yak', 'Ren geyiği', 'Angora keçisi'], 'Alpaka, And Dağları\'nın yüksek platolarında yumuşak ve sıcak tutan yünü için yetiştirilir; Peru başlıca yetiştirici ülkedir.'),
  ('Yeni Zelanda\'nın koyun eti ve süt ürünleri ihracatında öne çıkmasını sağlayan doğal koşul aşağıdakilerden hangisidir?', 'Yıl boyu yeşil kalan otlaklar', ['Geniş çöl alanları', 'Sürekli donmuş topraklar', 'Muson yağışlarıyla beslenen çeltik alanları'], 'Okyanusal iklimin ılık ve yağışlı yapısı otların yıl boyu büyümesini sağlar; hayvanlar kışın da açıkta otlayabildiği için üretim maliyeti düşüktür.'),
  ('Hindistan\'da sığırın kesilmesinin dinî nedenlerle büyük ölçüde sınırlı olmasına karşın büyükbaş hayvan sayısının çok yüksek olması en çok hangi ürünle ilişkilidir?', 'Süt üretimi', ['Sığır eti ihracatı', 'Yapağı üretimi', 'Kürk ticareti'], 'Hindistan\'da inek ve manda ağırlıkla süt ve iş gücü için beslenir; ülke dünyanın en büyük süt üreticisi konumundadır.'),
  ('Ankara keçisinin (Angora) uzun ve parlak liflerinden elde edilen ve tekstilde değerli olan lif hangisidir?', 'Tiftik', ['Kaşmir', 'Yapağı', 'İpek'], 'Tiftik (moher), Ankara keçisinin lifidir; bu keçi ırkı daha sonra Güney Afrika ve ABD\'ye de götürülerek yetiştirilmiştir.'),
  ('İpekböcekçiliği hangi ağacın yetiştirilmesine bağlıdır?', 'Dut', ['Meşe', 'Kestane', 'Kavak'], 'İpekböceği tırtılları yalnız dut yaprağıyla beslenir; bu nedenle ipek üretimi dut bahçelerinin bulunduğu yerlerde gelişir.'),
  ('Dünyada en çok pirinç üreten iki ülke hangi seçenekte birlikte verilmiştir?', 'Çin ve Hindistan', ['Tayland ve Vietnam', 'Japonya ve Filipinler', 'Mısır ve İtalya'], 'Çin ve Hindistan geniş çeltik alanları ve kalabalık nüfuslarıyla pirinç üretiminde uzun süredir açık ara ilk iki sıradadır.'),
  ('Mısır bitkisinin anavatanı neresidir?', 'Mezoamerika (bugünkü Meksika)', ['Mezopotamya (Dicle-Fırat arası)', 'Doğu Afrika', 'Güneydoğu Asya'], 'Mısır, binlerce yıl önce Meksika\'da teosinte adlı yabani bir otun evcilleştirilmesiyle ortaya çıkmış, Kolomb\'dan sonra dünyaya yayılmıştır.'),
  ('Kinoa adlı tahıl benzeri tohumun geleneksel üretim alanı neresidir?', 'And Dağları\'nın yüksek platoları', ['Sahra\'nın vahaları', 'Ganj Ovası', 'İskandinavya\'nın kıyıları'], 'Kinoa, Bolivya ve Peru\'nun Altiplano platosunda binlerce yıldır yetiştirilen, soğuğa ve kuraklığa dayanıklı bir bitkidir.'),
  ('Palm yağı üretiminde dünyada açık ara ilk iki sırayı paylaşan ülkeler hangi seçenekte birlikte verilmiştir?', 'Endonezya ve Malezya', ['Brezilya ve Arjantin', 'Nijerya ve Gana', 'Hindistan ve Pakistan'], 'Yağ palmiyesi Batı Afrika kökenlidir, ancak 20. yüzyılda Malezya ve Endonezya\'da kurulan plantasyonlar bu iki ülkeyi üretimin merkezi yapmıştır.'),
  ('Pamuğun hasat döneminde kurak hava istemesinin nedeni nedir?', 'Açılan kozaların yağmurla ıslanıp kalitesinin bozulması', ['Pamuğun yalnız karla beslenmesi', 'Kuraklıkta kozaların daha hızlı açılmaması', 'Yağmur suyunun pamuk tarlasında toprağı hızla tuzlandırması'], 'Pamuk büyüme döneminde bol su ve sıcaklık ister, ancak kozalar açıldıktan sonra yağış lifleri ıslatıp kirletir ve kaliteyi düşürür.'),
  ('Doğal kauçuk ağacının (Hevea brasiliensis) anavatanı neresidir?', 'Amazon Havzası', ['Malay Yarımadası', 'Kongo Havzası', 'Madagaskar'], 'Kauçuk ağacı Amazon ormanlarına özgüdür; 1876\'da tohumlarının İngiltere aracılığıyla Asya\'ya götürülmesiyle üretim Güneydoğu Asya\'ya kaydı.'),
  ('Kahve bitkisinin anavatanı kabul edilen bölge hangisidir?', 'Etiyopya yaylaları', ['Brezilya\'nın kıyı ovaları', 'Endonezya\'nın Java Adası', 'Kolombiya\'nın And yamaçları'], 'Arabika kahvesinin yabani olarak yetiştiği yer Etiyopya\'nın güneybatısıdır; bitki buradan Yemen\'e, oradan dünyaya yayılmıştır.'),
  ('Uzun süredir dünyanın en büyük kahve üreticisi olan ülke hangisidir?', 'Brezilya', ['Etiyopya', 'Kolombiya', 'Yemen'], 'Brezilya 19. yüzyıldan bu yana kahve üretiminde dünyada birinci sıradadır; São Paulo ve Minas Gerais başlıca üretim alanlarıdır.'),
  ('Hindistan\'ın kuzeydoğusunda, Brahmaputra vadisinde yer alan ve adını taşıyan sert, koyu çayıyla ünlü bölge hangisidir?', 'Assam', ['Kerala', 'Pencap', 'Gucerat'], 'Assam bölgesinde yerli bir çay çeşidi bulunmuş, 19. yüzyılda İngilizler burada geniş çay plantasyonları kurmuştur.'),
  ('Dünya kakao üretiminde uzun süredir birinci sırada olan ülke hangisidir?', 'Fildişi Sahili', ['Brezilya', 'Ekvador', 'Endonezya'], 'Fildişi Sahili 1970\'lerin sonundan bu yana kakao üretiminde dünyada birinci sıradadır; komşusu Gana ikinci büyük üreticidir.'),
  ('Şeker kamışı ile şeker pancarı karşılaştırıldığında aşağıdakilerden hangisi doğrudur?', 'Kamış tropikal-subtropikal, pancar ılıman bölgelerde yetişir', ['Kamış ılıman bölgelerde, pancar ise yalnız tropikal bölgelerde yetişir', 'İkisi de yalnız çöl vahalarında yetiştirilir', 'Pancar ağaç, kamış ise yumrulu bir bitkidir'], 'Şeker kamışı sıcak ve nemli koşullar ister; şeker pancarı ise Avrupa ve ılıman bölgelerin ürünüdür.'),
  ('Muzun ticari üretiminde ihracat amaçlı muzun hasatta yeşil koparılmasının nedeni nedir?', 'Uzun taşıma süresince olgunlaşarak pazara sağlam ulaşması', ['Yeşil muzun sarı muzdan daha tatlı olması', 'Olgun muzun hasat edilmesinin yasak olması', 'Muzun ağaçta bırakıldığında hiçbir zaman sararamaması'], 'Muz hasattan sonra da olgunlaşabilen bir meyvedir; yeşil koparılıp soğutmalı gemilerle taşınır, varış ülkesinde olgunlaştırma odalarında sarartılır.'),
  ('Vanilya bitkisinin dünya üretiminde uzun süredir öne çıkan ada ülkesi hangisidir?', 'Madagaskar', ['Yeni Zelanda', 'Malta', 'İrlanda'], 'Vanilya Meksika kökenli bir orkidedir; bugün dünya üretiminin büyük kısmı Madagaskar\'ın kuzeydoğusundaki plantasyonlardan gelir.'),
  ('Manyok (kassava) bitkisinin tropikal Afrika\'da yaygın bir temel besin olmasının nedeni hangisidir?', 'Yoksul topraklarda ve kuraklıkta da ürün verebilmesi', ['Yalnız sulanan çeltik tarlalarında yetişmesi', 'Kışın donlara çok dayanıklı olması', 'Hasadının yalnız makineyle yapılabilmesi'], 'Manyok besince yoksul topraklara ve düzensiz yağışa dayanıklıdır, yumrusu toprakta aylarca bekletilebilir; bu da onu güvenilir bir besin kaynağı yapar.'),
  ('Turunçgil (narenciye) ihracatında Akdeniz havzasında en önde gelen ülkelerden biri olup Valencia bölgesiyle tanınan ülke hangisidir?', 'İspanya', ['Romanya', 'Danimarka', 'Hollanda'], 'Valencia ve Murcia bölgeleri İspanya\'yı Avrupa\'nın en büyük portakal ve mandalina ihracatçısı yapmıştır.'),
  ('Üzüm bağcılığında dünyanın en büyük şarap üreticileri arasında yer alan İtalya, Fransa ve İspanya\'nın ortak coğrafi özelliği aşağıdakilerden hangisidir?', 'Asmaya uygun ılıman iklim ve uzun bağcılık geleneği', ['Tropikal yağmur ormanı iklimine sahip olmaları', 'Sürekli donmuş toprakların ve tundra bitki örtüsünün yaygın olması', 'Muson yağışlarının etkili olması'], 'Asma ılıman, güneşli yazları ve ılık kışları sever; bu üç ülkenin uzun bağcılık geleneği de onları dünya şarap üretiminin başına taşımıştır.'),
  ('ABD\'de Ohio\'dan Nebraska\'ya uzanan, mısır ve soya tarımının yanı sıra domuz ve sığır besiciliğinin de yoğun olduğu tarım bölgesine ne ad verilir?', 'Mısır Kuşağı (Corn Belt)', ['Pamuk Kuşağı (Cotton Belt)', 'Pas Kuşağı (Rust Belt)', 'Güneş Kuşağı (Sun Belt)'], 'Ortabatı\'daki Mısır Kuşağı verimli topraklar ve yeterli yaz yağışlarıyla mısır üretimine çok uygundur; üretilen mısırın önemli bölümü hayvan yemine gider.'),
  ('Pakistan ile Hindistan arasında paylaşılan, adı Farsçada ‘beş su’ anlamına gelen ve İndus kollarıyla sulanan verimli tarım bölgesi hangisidir?', 'Pencap', ['Keşmir', 'Sind', 'Batı Bengal'], 'Pencap, İndus\'un beş kolu (Jhelum, Chenab, Ravi, Beas, Sutlej) arasında kalır; geniş kanal sulama ağı sayesinde buğday ve pirinç ambarıdır.'),
  ('Ukrayna\'nın tarih boyunca ‘Avrupa\'nın tahıl ambarı’ olarak anılmasının temel coğrafi nedeni nedir?', 'Geniş düzlüklerde çok verimli kara toprakların bulunması', ['Ülkenin tamamının tropikal iklimde bulunması', 'Yıl boyu dağlardan inen buzul sularıyla bütün ovaların sulanabilmesi', 'Tarım alanlarının tamamının seralardan oluşması'], 'Ukrayna bozkırlarındaki derin ve humusça zengin topraklar, geniş düz arazi ile birleşince buğday, mısır ve ayçiçeği üretimini çok verimli kılar.'),
  ('Buğday ve arpanın ilk kez evcilleştirildiği, Zagros ve Toros etekleri ile Levant\'ı içine alan yay biçimli bölgeye ne ad verilir?', 'Bereketli Hilal', ['Altın Üçgen', 'Sahel Kuşağı', 'Kara Toprak Kuşağı'], 'Yaklaşık 10-11 bin yıl önce Bereketli Hilal\'de yabani tahıllar evcilleştirilmiş, tarım buradan Avrupa\'ya ve Asya\'ya yayılmıştır.'),
  ('Patatesin anavatanı neresidir?', 'And Dağları', ['İrlanda', 'Orta Avrupa ovaları', 'Hindistan alt kıtasının kuzeyi'], 'Patates And Dağları\'nda, Titikaka Gölü çevresinde evcilleştirilmiştir; Avrupa\'ya 16. yüzyılda İspanyollar aracılığıyla ulaşmıştır.'),
  ('Avrupalıların Amerika\'ya ulaşmasından sonra iki yarı küre arasında bitki, hayvan ve hastalıkların karşılıklı yayılmasına ne ad verilir?', 'Kolomb Değişimi', ['Yeşil Devrim', 'Neolitik Devrim', 'Merkantil Dönüşüm'], 'Kolomb Değişimi ile mısır, patates, domates Eski Dünya\'ya; buğday, şeker kamışı, at ve sığır Yeni Dünya\'ya taşındı.'),
  ('Bitkilerin toprak yerine besin çözeltisi içeren suda yetiştirildiği tarım yöntemine ne ad verilir?', 'Hidroponik tarım', ['Teraslı tarım', 'Kuru tarım', 'Nadas tarımı'], 'Hidroponik sistemlerde bitki kökleri mineral besinli suyla beslenir; su tasarrufu sağlar ve toprağı verimsiz ya da az olan yerlerde üretimi mümkün kılar.'),
  ('Kent içindeki kapalı binalarda ürünlerin üst üste raflarda, yapay ışık ve denetimli iklimle yetiştirilmesine ne ad verilir?', 'Dikey tarım', ['Ekstansif tarım', 'Göçebe tarım', 'Transhümans'], 'Dikey tarım arazi kullanımını en aza indirir ve üretimi tüketiciye yaklaştırır; ancak enerji gereksinimi yüksektir.'),
  ('Norveç\'in fiyortlarında büyük ölçekte yapılan ve ülkeyi dünyanın lider ihracatçısı yapan su ürünleri yetiştiriciliği hangi balıkla ilgilidir?', 'Atlantik somonu', ['Mavi yüzgeçli ton balığı', 'Hamsi', 'Tilapia'], 'Norveç fiyortlarının korunaklı, serin ve temiz suları ağ kafeslerde somon yetiştirmeye çok uygundur; ülke çiftlik somonunda dünya lideridir.'),
  ('Balıkların kontrollü koşullarda havuz ya da kafeslerde yetiştirilmesine genel olarak ne ad verilir?', 'Akuakültür', ['Trol avcılığı', 'Paraketa avcılığı', 'Gırgır avcılığı'], 'Akuakültür, doğal stoklar üzerindeki baskıyı azaltma amacıyla balık, karides, midye gibi canlıların yetiştirilmesidir; Çin bu alanda dünyada açık ara birincidir.'),
  ('Güneydoğu Asya\'da karides çiftlikleri kurmak için kıyı ormanlarının kesilmesi en çok hangi ekosistemi tehdit etmektedir?', 'Mangrov ormanlarını', ['Tundra bitki örtüsünü', 'Tayga ormanlarını', 'Alpin çayırları'], 'Tayland, Endonezya, Vietnam gibi ülkelerde karides havuzları için geniş mangrov alanları yok edilmiş, kıyılar dalgalara karşı korumasız kalmıştır.'),
  ('Kanada, Rusya ve İskandinav ülkelerinin kereste, kâğıt hamuru ve kâğıt üretiminde öne çıkmasının temel kaynağı hangi orman kuşağıdır?', 'Tayga (boreal) ormanları', ['Tropikal yağmur ormanları', 'Akdeniz makileri', 'Savan ağaçlıkları'], 'Tayga kuşağındaki çam, ladin ve köknar gibi yumuşak odunlu iğne yapraklılar geniş saf meşcereler oluşturur; bu da sanayi ölçeğinde kesimi kolaylaştırır.'),
  ('Kanada ve Finlandiya\'da tarihsel olarak kesilen tomrukların fabrikaya taşınmasında hangi doğal ulaşım yolundan yararlanılmıştır?', 'Akarsu ve göllerde tomrukların yüzdürülmesi', ['Çöl kervan yolları', 'Muson rüzgârlarıyla yelkenli taşımacılık', 'Tomrukların buzul yarıklarından aşağı kaydırılarak vadiye indirilmesi'], 'Göl ve akarsuyu bol olan bu ülkelerde tomruklar ilkbahar kar erimesiyle akarsulara bırakılır, kereste ve kâğıt fabrikalarına yüzdürülerek ulaştırılırdı.'),
  ('Maun ve tik gibi değerli sert ağaçlar hangi orman kuşağının ürünüdür?', 'Tropikal ormanlar', ['Tayga ormanları', 'Tundra çalılıkları', 'Ilıman çam ormanları'], 'Maun (Orta ve Güney Amerika) ile tik (Güney ve Güneydoğu Asya) tropikal kuşakta yetişen, mobilya ve gemi yapımında değerli sert odunlardır.'),
  ('Kanada\'nın Quebec eyaleti dünya üretiminin büyük bölümünü karşıladığı hangi orman ürünüyle tanınır?', 'Akçaağaç şurubu', ['Kauçuk', 'Hindistan cevizi yağı', 'Palmiye yağı'], 'Şeker akçaağacının ilkbaharda toplanan özsuyu kaynatılarak şurup elde edilir; Quebec dünya üretiminin büyük kısmını sağlar.'),
  ('Bir orman işletmesinin ürünlerinin sürdürülebilir yönetilen ormanlardan geldiğini belgeleyen uluslararası sertifika sistemine örnek aşağıdakilerden hangisidir?', 'FSC', ['Kimberley Süreci sertifikası', 'OPEC üretim kotası belgesi', 'IATA uçuş güvenliği belgesi'], 'FSC etiketi, kerestenin ya da kâğıdın çevresel ve sosyal ölçütlere uygun yönetilen ormanlardan geldiğini tüketiciye gösterir.'),
  ('Bir çiftçi 250 dekarlık tarlasından dekar başına ortalama 400 kg buğday almıştır. Toplam üretim kaç tondur?', '100', ['10', '1.000', '62,5'], '250 × 400 = 100.000 kg eder; 1 ton 1.000 kg olduğundan üretim 100 tondur.'),
  ('Yeşil Devrim sonrası bir ülkede tahıl ekim alanı değişmezken verim hektar başına 1,5 tondan 3 tona çıkmıştır. Bu ülkenin tahıl üretimi için aşağıdakilerden hangisi söylenebilir?', 'Üretim iki katına çıkmıştır', ['Üretim yarıya inmiştir', 'Üretim değişmemiştir', 'Üretim dört katına çıkmıştır'], 'Üretim = alan × verimdir; alan sabitken verimin iki katına çıkması üretimi de iki katına çıkarır.'),
  ('Bir demir cevherinin ‘yüksek tenörlü’ olması ne anlama gelir?', 'Cevherdeki metal oranının yüksek olması', ['Cevherin yer yüzeyine çok yakın olup açık ocakla çıkarılabilmesi', 'Cevherin manyetik olmaması', 'Cevherin sıvı hâlde bulunması'], 'Tenör, cevherdeki değerli metalin yüzdesidir; tenör yükseldikçe aynı miktar metal için daha az kaya işlenir ve maliyet düşer.'),
  ('Kömür oluşumuna (kömürleşme) en uygun ortam aşağıdakilerden hangisidir?', 'Bitki kalıntılarının oksijensiz bataklıklarda birikip gömülmesi', ['Çöl kumlarının rüzgârla taşınması', 'Mercanların sığ denizde birikmesi', 'Lav akıntılarının deniz suyuyla karşılaşıp hızla soğuması'], 'Bataklık ortamında oksijen az olduğundan bitki kalıntıları tam çürümez; üzerleri tortulla örtülüp gömülünce zamanla kömüre dönüşür.'),
  ('Endüstri Devrimi\'nin 18. yüzyılda ilk olarak Britanya\'da başlamasında doğal kaynaklar açısından en etkili etken hangisidir?', 'Kömür ve demir yataklarının birbirine yakın ve bol olması', ['Ülkenin geniş tropikal ormanlara sahip olması', 'Petrol yataklarının yüzeyde bulunması', 'Ülkenin hiçbir denize kıyısının olmaması'], 'Britanya\'da kömür, demir cevheri ve suyolları bir aradaydı; buhar makinesinin yakıtı olan kömürün kolay bulunması sanayileşmeyi hızlandırdı.'),
  ('Kömür madenciliğinde ‘grizu patlaması’ hangi gazın birikmesiyle ilişkilidir?', 'Metan', ['Oksijen', 'Azot', 'Helyum'], 'Kömür damarlarından sızan metan havayla belirli oranlarda karışınca patlayıcı olur; bu, yeraltı kömür madenlerinin en büyük tehlikelerinden biridir.'),
  ('Petrolün büyük çoğunluğunun hangi kökenden oluştuğu kabul edilir?', 'Deniz tabanında gömülen mikroskobik canlı kalıntılarından', ['Volkanik lavların soğumasından', 'Karada biriken büyük dinozor ve memeli kemiklerinin çözünmesinden', 'Meteor çarpmalarıyla gelen maddeden'], 'Plankton ve algler gibi küçük deniz canlılarının kalıntıları oksijensiz tortullarda gömülüp ısı ve basınçla milyonlarca yılda petrole dönüşür.'),
  ('Kuzey Denizi\'ndeki petrol üretiminden en çok pay alan iki ülke hangi seçenekte birlikte verilmiştir?', 'Norveç ve Birleşik Krallık', ['Danimarka ve Polonya', 'Belçika ve İzlanda Cumhuriyeti', 'Fransa ve İrlanda'], 'Kuzey Denizi\'nin kıta sahanlığı ağırlıkla Norveç ve Birleşik Krallık arasında bölüşülmüştür; 1970\'lerden beri büyük açık deniz sahaları işletilmektedir.'),
  ('Doğal gazın kömüre göre ‘daha temiz’ fosil yakıt sayılmasının temel nedeni nedir?', 'Birim enerji başına daha az CO₂ ve hava kirletici salması', ['Hiç karbon içermemesi', 'Yenilenebilir bir kaynak olup tükenme riskinin bulunmaması', 'Yanınca yalnız oksijen üretmesi'], 'Doğal gaz (ağırlıkla metan) yandığında aynı enerji için kömürün yaklaşık yarısı kadar CO₂ açığa çıkarır; kükürt dioksit ve kül salımı da çok düşüktür.'),
  ('Bir ülkenin kanıtlanmış petrol rezervi 30 milyar varil, yıllık üretimi 1,5 milyar varildir. Üretim ve rezerv değişmezse rezerv yaklaşık kaç yıl yeter?', '20', ['45', '15', '30'], 'Rezerv/üretim oranı = 30 / 1,5 = 20 yıldır. Gerçekte yeni keşifler ve teknoloji bu süreyi değiştirebilir.'),
  ('Dünya bakır üretiminde uzun süredir birinci sırada olan ve Chuquicamata, Escondida gibi dev madenlere sahip ülke hangisidir?', 'Şili', ['Arjantin', 'Kolombiya', 'Uruguay'], 'Şili, And Dağları\'ndaki porfiri bakır yataklarıyla dünya bakır üretiminin yaklaşık dörtte birini sağlar.'),
  ('Bakırın elektrik tesisatı ve kablolarda en çok kullanılan metal olmasının temel nedeni hangisidir?', 'Elektriği çok iyi iletmesi ve kolay işlenmesi', ['Mıknatıs tarafından çok güçlü çekilmesi', 'Erime sıcaklığının oda sıcaklığından düşük olması', 'Doğada saf hâlde hiç bulunmaması nedeniyle değerli sayılması'], 'Bakır gümüşten sonra en iyi iletken metaldir, ucuzdur ve tel hâline kolayca getirilebilir; bu nedenle elektrifikasyonun temel metalidir.'),
  ('Demiri paslanmaya karşı korumak amacıyla çinkoyla kaplama işlemine ne ad verilir?', 'Galvanizleme', ['Kalaylama', 'Damıtma', 'Kavurma'], 'Galvanizlemede çelik erimiş çinkoya batırılır; çinko demirden önce oksitlenerek onu korur. Dünya çinko tüketiminin yaklaşık yarısı bu amaçla kullanılır.'),
  ('Bakır ile kalayın karıştırılmasıyla elde edilen ve insanlık tarihinde bir çağa adını veren alaşım hangisidir?', 'Tunç', ['Pirinç', 'Çelik', 'Lehim'], 'Tunç Çağı\'nda bakır ve kalay alaşımı alet ve silah yapımında kullanıldı; kalay nadir olduğundan uzak mesafeli ticaret yolları gelişti.'),
  ('1848\'de Sutter\'s Mill\'de altın bulunmasıyla başlayan ve San Francisco\'nun hızla büyümesine yol açan altına hücum hangi ABD eyaletinde yaşanmıştır?', 'Kaliforniya', ['Teksas', 'Alaska', 'Kuzey Karolina'], 'Kaliforniya Altına Hücumu 1849\'da on binlerce kişiyi bölgeye çekti; San Francisco küçük bir yerleşmeden kısa sürede büyük bir liman kentine dönüştü.'),
  ('Şili, Arjantin ve Bolivya\'nın tuz düzlüklerindeki büyük rezervleri nedeniyle bu bölge hangi metal için ‘üçgen’ olarak anılır?', 'Lityum', ['Uranyum', 'Kobalt', 'Tungsten'], 'And Dağları\'nın yüksek platolarındaki tuzlalarda (salar) lityum, tuzlu sulardan buharlaştırma havuzlarıyla elde edilir; bu üç ülke ‘Lityum Üçgeni’ olarak anılır.'),
  ('Lityum ve kobalt gibi metallerin son yıllarda ‘kritik mineral’ olarak anılmasının en önemli nedeni hangisidir?', 'Şarj edilebilir pillerde ve enerji dönüşümünde vazgeçilmez olmaları', ['Gıda üretiminde temel besin olmaları', 'Yalnız süs eşyası yapımında kullanılmaları', 'Doğada her yerde bol bulunmaları'], 'Elektrikli araçlar ve enerji depolama, lityum iyon pillere dayanır; bu metallerin üretiminin birkaç ülkede yoğunlaşması arz güvenliği kaygısı yaratır.'),
  ('Fosfat kayasının dünyada en çok hangi amaçla kullanıldığı bilinir?', 'Tarımsal gübre üretimi', ['Cam üretimi', 'Paslanmaz çelik alaşımı yapımı', 'Uçak yakıtı'], 'Fosfor bitkiler için temel besin maddelerinden biridir; çıkarılan fosfatın büyük kısmı fosforlu gübrelere dönüştürülür.'),
  ('Deniz tuzu üretmek için deniz suyunun sığ havuzlarda güneş ve rüzgârla buharlaştırıldığı tesislere ne ad verilir?', 'Tuzla', ['Polder', 'Salar', 'Fiyort'], 'Tuzlalarda deniz suyu sığ havuzlara alınır, su buharlaştıkça tuz kristalleşir. Bu yöntem sıcak, kurak ve rüzgârlı kıyılarda verimlidir.'),
  ('Maden yatağının yüzeye yakın olduğu durumlarda üstteki toprak ve kayalar kaldırılarak cevherin basamaklı büyük çukurlarda çıkarılmasına ne ad verilir?', 'Açık ocak madenciliği', ['Kuyu (galeri) madenciliği', 'Yerinde liç', 'Plaser yıkama'], 'Açık ocak yönteminde maliyet düşük ve güvenlik görece yüksektir, ancak geniş arazi bozulur ve çok büyük miktarda pasa (atık kaya) oluşur.'),
  ('Bir maden şirketinin, işletme bittikten sonra açık ocak ve pasa alanlarını toprakla örtüp ağaçlandırması hangi uygulamaya örnektir?', 'Maden sahası rehabilitasyonu', ['Kentsel dönüşüm ve yeniden yapılanma', 'Ekstansif tarım', 'Monokültür'], 'Rehabilitasyon (ıslah), madencilikle bozulan arazinin yeniden kullanılabilir hâle getirilmesidir; pek çok ülkede yasal bir zorunluluktur.'),
  ('Bir akarsuyun hidroelektrik potansiyelini belirleyen iki temel etken hangi seçenekte birlikte verilmiştir?', 'Akım miktarı ve düşü yüksekliği', ['Suyun rengi ve sıcaklığı', 'Akarsuyun toplam uzunluğu ve suyunun tuzluluk oranı', 'Havzadaki nüfus ve kent sayısı'], 'Elde edilebilecek güç, düşen suyun debisi ile düşü (yükseklik farkı) çarpımıyla orantılıdır; bu yüzden bol sulu ve eğimli akarsular en elverişlidir.'),
  ('Norveç\'te elektriğin neredeyse tamamının hidroelektrikten elde edilebilmesini sağlayan coğrafi koşullar hangi seçenekte doğru verilmiştir?', 'Bol yağış, dağlık arazi ve buzul gölleri', ['Geniş ovalar ve kurak iklim', 'Volkanik etkinlik ve yer altından çıkan sıcak su kaynakları', 'Sürekli esen alize rüzgârları'], 'Atlantik\'ten gelen nemli hava dağlara çarparak bol yağış bırakır; yüksek platolardaki göller ve dik vadiler büyük düşü sağlar.'),
  ('Nükleer santrallerde elektrik üretiminin dayandığı temel fiziksel süreç hangisidir?', 'Uranyum çekirdeklerinin bölünmesi (fisyon)', ['Hidrojen çekirdeklerinin birleşmesi (füzyon)', 'Kömürün oksijenle yanması', 'Güneş ışığının doğrudan elektriğe dönüşmesi'], 'Ticari reaktörlerde uranyum-235 çekirdekleri nötronla bölünür; açığa çıkan ısı suyu buhara çevirir ve buhar türbini döndürür.'),
  ('1986\'da tarihin en ağır nükleer kazalarından birinin yaşandığı Çernobil santrali bugün hangi ülkenin topraklarındadır?', 'Ukrayna', ['Belarus', 'Rusya', 'Litvanya'], 'Çernobil santrali kuzey Ukrayna\'da, Pripyat kenti yakınındadır; kazanın radyoaktif bulutu en çok Belarus\'u ve Avrupa\'nın geniş bölümünü etkiledi.'),
  ('Güneş enerjisi santralleri için en elverişli yerler genellikle hangi özelliktedir?', 'Bulutsuz gün sayısı fazla, alçak enlemli kurak alanlar', ['Sürekli sisli ve yüksek enlemli kıyılar', 'Yıl boyu kar örtüsü bulunan kutup bölgeleri', 'Ekvatoral yağmur ormanlarının en yağışlı kesimleri'], 'Güneşlenme süresi ve ışınım şiddeti, açık havanın sürekli olduğu dönence çevresindeki çöllerde en yüksektir; Atacama, Sahra ve Arap Yarımadası örnektir.'),
  ('Danimarka\'nın elektriğinin önemli bir bölümünü rüzgârdan sağlayabilmesinin coğrafi nedeni nedir?', 'Alçak ve düz kıyıları ile Kuzey Denizi\'nden esen güçlü batı rüzgârları', ['Yüksek dağlarından inen sıcak fön rüzgârları', 'Ekvatora yakın olması nedeniyle esen alizeler', 'Volkanik etkinliğin rüzgâr oluşturması'], 'Orta enlemlerin batı rüzgârları Danimarka\'da engelle karşılaşmadan eser; sığ denizler de açık deniz rüzgâr çiftlikleri için uygundur.'),
  ('Açık deniz (offshore) rüzgâr santrallerinin karadakilere göre üstünlüğü aşağıdakilerden hangisidir?', 'Rüzgârın daha güçlü ve kesintisiz olması', ['Kurulum, kablolama ve bakım maliyetlerinin karadakilerden daha düşük olması', 'Hiç kablo bağlantısı gerektirmemesi', 'Fırtınalardan hiç etkilenmemesi'], 'Deniz yüzeyinde sürtünme az olduğundan rüzgâr daha hızlı ve düzenli eser; ancak kurulum, kablolama ve bakım maliyeti karadakinden yüksektir.'),
  ('Rüzgâr ve güneş enerjisinin elektrik şebekesi açısından en önemli sorunu olarak ‘kesintililik’ ne anlama gelir?', 'Üretimin hava koşullarına göre değişip her an talebi karşılayamaması', ['Kaynakların birkaç yıl içinde tükenmesi', 'Elektrik üretiminin çok kirletici olması', 'Santrallerin yalnız gece çalışabilmesi'], 'Güneş gece üretmez, rüzgâr değişkendir; bu nedenle depolama, esnek santraller ve geniş şebeke bağlantıları gereklidir.'),
  ('Brezilya\'da araçlarda yaygın olarak kullanılan biyoetanol çoğunlukla hangi bitkiden üretilir?', 'Şeker kamışı', ['Mısır', 'Ayçiçeği', 'Kolza'], 'Brezilya 1975\'teki Proálcool programıyla şeker kamışından etanol üretimini başlattı; esnek yakıtlı araçlar etanol ve benzini her oranda kullanabilir.'),
  ('ABD\'de üretilen biyoetanolün büyük bölümünün hammaddesi hangisidir?', 'Mısır', ['Şeker kamışı', 'Pirinç', 'Palmiye'], 'ABD\'de etanol ağırlıkla Mısır Kuşağı\'nda üretilen mısırdan elde edilir ve benzine karıştırılır.'),
  ('Kömür, petrol, doğal gaz, uranyum, rüzgâr ve güneş gibi doğada bulunduğu hâliyle kullanılan enerji kaynaklarına ne ad verilir?', 'Birincil enerji kaynakları', ['İkincil enerji kaynakları', 'Son enerji kaynakları', 'Dönüştürülmüş enerji kaynakları'], 'Birincil kaynaklar doğada hazır bulunur; elektrik, benzin ya da kok gibi bunlardan dönüştürülerek elde edilenler ise ikincil enerji olarak adlandırılır.'),
  ('Aşağıdakilerden hangisi ikincil enerji kaynağına örnektir?', 'Elektrik', ['Ham petrol', 'Doğal gaz', 'Güneş ışığı'], 'Elektrik doğada kullanıma hazır bulunmaz; kömür, gaz, su, rüzgâr gibi birincil kaynakların dönüştürülmesiyle üretildiği için ikincil enerjidir.'),
  ('Rusya\'dan Almanya\'ya doğal gazı transit ülkeler üzerinden geçmeden Baltık Denizi\'nin altından taşımak amacıyla inşa edilen boru hattı hangisidir?', 'Kuzey Akım', ['Druzhba', 'TAP', 'Transmed'], 'Nord Stream 1 2011\'de çalışmaya başladı; Vyborg yakınından Almanya\'nın Greifswald kıyısına uzanır. Hatlar 2022\'de patlamalarla ağır hasar gördü.'),
  ('Bir termik santralde 1.000 birim yakıt enerjisinden 380 birim elektrik elde edilmektedir. Santralin verimi yüzde kaçtır?', '38', ['62', '26', '100'], 'Verim = elde edilen elektrik / harcanan enerji × 100 = 380 / 1.000 × 100 = %38; geri kalan enerji büyük ölçüde atık ısı olarak kaybolur.'),
  ('Mart 2021\'de Süveyş Kanalı\'nda karaya oturarak kanalı yaklaşık altı gün tıkayan ve küresel ticarette gecikmelere yol açan konteyner gemisi hangisidir?', 'Ever Given', ['Exxon Valdez', 'Titanic', 'Queen Mary 2'], 'Ever Given\'ın kumsala saplanması yüzlerce geminin beklemesine neden olmuş, dar geçitlerin küresel tedarik zincirleri için ne kadar kritik olduğunu göstermiştir.'),
  ('Saint Lawrence Deniz Yolu\'nun yılın birkaç ayında kapalı kalmasının nedeni nedir?', 'Kış aylarında suların donması', ['Yaz aylarında suların kuruması', 'Kasırga mevsiminin uzun sürmesi', 'Gelgit genliğinin çok yükselmesi'], 'Kanada\'nın sert karasal kışında göller ve nehir buzla kaplanır; deniz yolu genellikle aralık sonundan mart sonuna kadar kapanır.'),
  ('Dünya deniz ticaretinde ‘darboğaz’ (chokepoint) olarak anılan su yollarının ortak özelliği nedir?', 'Çok sayıda geminin geçmek zorunda olduğu dar geçitler olması', ['Tamamının insan eliyle kazılmış yapay su yolları olması', 'Gemilerin buralardan geçişinin yasak olması', 'Her birinin tek bir ülkenin topraklarıyla çevrili olması'], 'Hürmüz, Malakka, Babülmendep, Süveyş ve Panama gibi darboğazlarda kısa süreli bir kapanma bile küresel enerji ve mal arzını etkileyebilir.'),
  ('Konteyner taşımacılığında kullanılan ‘TEU’ birimi neyi ifade eder?', '20 fit uzunluğundaki standart konteyner eşdeğerini', ['Bir geminin taşıyabileceği yükün ton cinsinden azami ağırlığını', 'Limandaki vinç sayısını', 'Bir konteynerin içindeki palet sayısını'], 'TEU (Twenty-foot Equivalent Unit), 20 fitlik konteyneri temel alır; 40 fitlik bir konteyner 2 TEU sayılır. Liman ve gemi kapasiteleri bu birimle ölçülür.'),
  ('Bir limanın büyük gemileri kabul edebilmesi için en önemli fiziksel özelliği hangisidir?', 'Yeterli su derinliği', ['Kıyıda kumsal bulunması', 'Limanın kuzeye bakması', 'Yakınında nehir deltası olması'], 'Büyük konteyner gemileri ve tankerler 15-20 metreyi aşan su çekimine sahiptir; derinliği yetersiz limanlar tarama yapmak ya da açıkta yeni terminal kurmak zorunda kalır.'),
  ('Sahra-ötesi ticaretin büyük ölçüde gelişmesini sağlayan ve 3-4. yüzyıllardan itibaren Kuzey Afrika\'da yaygınlaşan ulaşım aracı hangisidir?', 'Tek hörgüçlü deve', ['Tekerlekli at arabası', 'Fil', 'Lama'], 'Deve uzun süre susuz kalabilir ve kumda yürüyebilir; devenin yaygınlaşmasıyla Sahra\'yı aşan uzun kervan yolculukları mümkün hâle geldi.'),
  ('Avrupa\'dan Afrika\'nın güneyini dolaşarak Hindistan\'a ulaşan ilk deniz seferini 1498\'de Kalikut\'a vararak tamamlayan Portekizli denizci kimdir?', 'Vasco da Gama', ['Bartolomeu Dias', 'Kristof Kolomb', 'Ferdinand Macellan'], 'Vasco da Gama\'nın seferi baharata Orta Doğu aracılarını atlayarak deniz yoluyla ulaşmayı mümkün kıldı ve Portekiz\'in Hint Okyanusu ticaret imparatorluğunu başlattı.'),
  ('Moskova\'yı Pasifik kıyısındaki Vladivostok\'a bağlayan, yaklaşık 9.300 km uzunluğuyla dünyanın en uzun demiryolu hattı hangisidir?', 'Trans-Sibirya Demiryolu', ['Baykal-Amur Ana Hattı', 'Hicaz Demiryolu', 'Bağdat Demiryolu'], 'Yapımına 1891\'de başlanan hat 1916\'da tamamlandı; Sibirya\'nın kaynaklarının işletilmesinde ve Rusya\'nın Uzak Doğu\'ya bağlanmasında temel rol oynadı.'),
  ('Pan-Amerikan Karayolu\'nun Alaska\'dan Arjantin\'e kadar kesintisiz olmamasının nedeni nedir?', 'Panama ile Kolombiya arasındaki Darién bölgesinin yolsuz olması', ['Yolun Amazon Nehri\'ni hiçbir köprüyle geçememesi', 'Yolun Panama Kanalı\'nı geçememesi', 'And Dağları\'nın hiç aşılamaması'], 'Darién Boşluğu yaklaşık 100 km\'lik bir yağmur ormanı ve bataklık alanıdır; çevresel ve güvenlik nedenleriyle buraya yol yapılmamıştır.'),
  ('Çin\'in 2013\'te duyurduğu ve Asya, Avrupa ve Afrika\'yı kara ve deniz yoluyla bağlayan liman, demiryolu ve karayolu yatırımlarını kapsayan girişimi hangi adla bilinir?', 'Kuşak ve Yol Girişimi', ['Marshall Planı', 'Büyük Yeşil Duvar ağaçlandırma projesi', 'Büyük İleri Atılım'], 'Girişimin ‘kuşak’ kısmı İpek Yolu Ekonomik Kuşağı\'nı (kara), ‘yol’ kısmı ise 21. Yüzyıl Deniz İpek Yolu\'nu ifade eder.'),
  ('İç su yolu taşımacılığının karayoluna göre dezavantajı aşağıdakilerden hangisidir?', 'Yavaş olması ve güzergâhın su yollarıyla sınırlı kalması', ['Ton başına yakıt tüketiminin bütün taşıma türleri arasında en yüksek olması', 'Ağır yük taşıyamaması', 'Trafik kazalarının çok sık olması'], 'Su yolları yalnız nehir ve kanalların bulunduğu yerlere ulaşabilir; kuraklıkta su seviyesinin düşmesi, kışın donma ve yavaşlık başlıca sınırlamalardır.'),
  ('Üretim sürecinde ağırlığının büyük bölümünü kaybeden ham maddeleri işleyen sanayiler, örneğin bakır izabesi, genellikle nereye kurulur?', 'Ham madde kaynağının yakınına', ['Pazarın tam ortasına', 'Ham madde ile pazardan uzak bir yere', 'Yalnız başkentlere'], 'Ağırlık kaybeden süreçlerde ürün ham maddeden çok daha hafiftir; işlenmiş ürünü taşımak ham maddeyi taşımaktan ucuz olduğu için tesis ham maddeye yakın kurulur.'),
  ('Hazır giyim sanayisinin son 40 yılda büyük ölçüde Bangladeş, Vietnam gibi ülkelere kaymasının en önemli nedeni hangisidir?', 'Emek yoğun üretimde işgücünün ucuz olması', ['Bu ülkelerde büyük pamuk fazlası bulunması', 'Tekstil makinelerinin yalnız bu ülkelerde çalışabilmesi', 'Bu ülkelerin Avrupa\'ya kara yoluyla bağlı olması'], 'Dikiş işi makineleşmeye görece dirençlidir ve çok sayıda işçi gerektirir; bu nedenle üretim ücretlerin düşük olduğu ülkelere yönelir.'),
  ('Bir fabrikanın üretim miktarı arttıkça ürün başına düşen sabit maliyetin azalmasına ne ad verilir?', 'Ölçek ekonomisi', ['Fırsat maliyeti', 'Enflasyon', 'Kaynak laneti'], 'Büyük ölçekli üretimde makine, bina ve yönetim gibi sabit maliyetler daha çok ürüne bölünür; bu da birim maliyeti düşürür.'),
  ('ABD\'nin kuzeydoğusunda ve Büyük Göller çevresinde, 1970\'lerden sonra çelik ve otomotiv fabrikalarının kapanmasıyla gerileyen eski sanayi kuşağına ne ad verilir?', 'Pas Kuşağı (Rust Belt)', ['Güneş Kuşağı (Sun Belt)', 'Mısır Kuşağı (Corn Belt)', 'İncil Kuşağı (Bible Belt)'], 'Pittsburgh, Detroit, Cleveland gibi kentlerde ağır sanayinin küçülmesi işsizliğe ve nüfus kaybına yol açtı; terk edilen fabrikalar bölgeye adını verdi.'),
  ('Detroit\'in 20. yüzyılda ‘Motor Kenti’ (Motor City) olarak anılmasının nedeni nedir?', 'Ford, General Motors ve Chrysler gibi büyük otomobil şirketlerinin merkezi olması', ['Dünyanın ilk motorlu teknesinin ve ilk dizel motorunun burada yapılıp denenmesi', 'Kentte hiç otomobil kullanılmaması', 'Kentin bir motor yarışı pistine kurulması'], 'Henry Ford\'un seri üretim bandıyla başlayan otomotiv sanayisi Detroit\'te yoğunlaştı; Büyük Göller üzerinden gelen çelik ve ham maddeler bu gelişmeyi destekledi.'),
  ('Kaliforniya\'da Stanford Üniversitesi çevresinde yarı iletken ve bilgisayar şirketlerinin kümelenmesiyle oluşan teknoloji bölgesine ne ad verilir?', 'Silikon Vadisi', ['Teknoloji Koridoru', 'Ölüm Vadisi', 'Güneş Vadisi'], 'Ad, çiplerin yapımında kullanılan silisyumdan (silikon) gelir; üniversite araştırmaları, risk sermayesi ve nitelikli işgücü bölgenin gelişiminde belirleyici oldu.'),
  ('Hindistan\'ın ‘Silikon Vadisi’ olarak anılan ve yazılım ile bilgi teknolojileri hizmetlerinin merkezi olan kent hangisidir?', 'Bengaluru', ['Kalküta (Kolkata) ve çevresi', 'Varanasi', 'Amritsar'], 'Bengaluru\'nun ılıman iklimi, eğitim ve araştırma kurumları ile İngilizce bilen mühendis havuzu, uluslararası yazılım şirketlerini kente çekti.'),
  ('Bir ülkede sanayinin ekonomideki ve istihdamdaki payının uzun dönemde azalmasına ne ad verilir?', 'Sanayisizleşme', ['Kentleşme', 'Yığılma', 'Kolonileşme'], 'Sanayisizleşme, ucuz işgücü ülkelerine üretimin kayması ve otomasyon gibi nedenlerle gelişmiş ülkelerde 1970\'lerden sonra belirgin biçimde yaşandı.'),
  ('ABD, Kanada ve Meksika arasında 1994\'te yürürlüğe giren ve 2020\'de yerini yeni bir anlaşmaya (USMCA) bırakan serbest ticaret anlaşması hangisidir?', 'NAFTA', ['EFTA', 'CAFTA', 'ECOWAS'], 'Kuzey Amerika Serbest Ticaret Anlaşması gümrük vergilerinin büyük bölümünü kaldırdı; özellikle otomotiv sanayisinde üç ülke arasında yoğun bir üretim ağı oluştu.'),
  ('Bir ülkenin başka bir ülkeyle ticareti siyasi nedenlerle tamamen ya da belirli mallarda yasaklamasına ne ad verilir?', 'Ambargo', ['Kota', 'Damping', 'Tarife'], 'Ambargo, ticari ilişkilerin bir yaptırım aracı olarak kesilmesidir; 1973 Arap petrol ambargosu bilinen örneklerdendir.'),
  ('Bir ülkenin belirli bir malın ithalatına yıllık miktar sınırı koymasına ne ad verilir?', 'Kota', ['Ambargo', 'Sübvansiyon', 'Devalüasyon'], 'Kota, ithalatı miktar olarak sınırlayan bir koruma önlemidir; vergi yerine doğrudan hacmi kısıtlar.'),
  ('Yerli üreticileri yabancı rekabetten korumak amacıyla gümrük vergileri ve kotalarla ithalatın sınırlandırılmasına dayanan politikaya ne ad verilir?', 'Korumacılık', ['Serbest ticaret', 'Küreselleşme', 'Liberalleşme'], 'Korumacılık genç sanayileri ve istihdamı korumayı amaçlar; ancak tüketici fiyatlarını yükseltebilir ve karşı önlemlere yol açabilir.'),
  ('Gelişmekte olan ülkelerdeki küçük üreticilere adil bir asgari fiyat ve sosyal prim ödenmesini amaçlayan ve kahve, kakao gibi ürünlerde etiketle tanınan hareket hangisidir?', 'Adil ticaret', ['Serbest bölge uygulaması', 'Kabotaj hakkı', 'Kolaylık bayrağı'], 'Adil ticaret etiketli ürünlerde üreticiye piyasa fiyatı düşse bile belirli bir taban fiyat ve topluluk projeleri için ek prim ödenir.'),
  ('Bir akıllı telefonun Amerika\'da tasarlanıp parçalarının Kore ve Japonya\'da üretilmesi, Çin\'de monte edilip dünyaya satılması hangi kavramı örnekler?', 'Küresel değer zinciri', ['Kendi kendine yeterlilik', 'Merkantilizm', 'Geçimlik üretim'], 'Üretim aşamaları farklı ülkelere dağılır; her ülke zincirde en avantajlı olduğu aşamayı üstlenir.'),
  ('Bir ülkenin ihracatı 2015\'te 200 milyar dolar, 2020\'de 260 milyar dolardır. İhracat bu dönemde yüzde kaç artmıştır?', '30', ['60', '23', '130'], 'Artış 260 − 200 = 60 milyar dolardır; 60 / 200 × 100 = %30.'),
  ('Filipinler\'in İngilizce konuşan genç nüfusu nedeniyle hızla büyüyen hizmet sektörü dalı hangisidir?', 'Çağrı merkezi ve iş süreçleri dış kaynak hizmetleri', ['Kömür madenciliği', 'Buğday tarımı', 'Gemi söküm ve hurda çelik geri dönüşüm tesisleri'], 'Filipinler ABD şirketlerinin müşteri hizmetleri ve arka ofis işlerini yürüten çağrı merkezleri için dünyanın önde gelen ülkelerinden biri hâline gelmiştir.'),
  ('Petrol tankeri kazalarından sonra tek cidarlı tankerlerin yerine çift cidarlı tankerlerin zorunlu hâle getirilmesinin amacı nedir?', 'Gövde delindiğinde petrolün denize sızmasını önlemek', ['Tankerlerin daha hafif olup daha hızlı seyretmesini ve seferleri kısaltmasını sağlamak', 'Tankerlerin daha az yakıt harcaması', 'Petrolün taşınırken ısınmasını önlemek'], 'Çift cidarda dış gövde ile yük tankı arasında boşluk bulunur; çarpma ya da karaya oturmada dış gövde delinse bile yük tankı zarar görmeyebilir.'),
  ('Japonya\'da 1950\'lerde Minamata Körfezi çevresinde görülen ve ‘Minamata hastalığı’ olarak bilinen salgının nedeni hangisidir?', 'Bir kimya fabrikasının denize bıraktığı cıvanın balıklarda birikmesi', ['Yakındaki bir nükleer santralden körfeze sızan radyoaktif soğutma suyu', 'Pirinç tarlalarında kullanılan aşırı gübre', 'Volkan patlamasıyla yayılan kül'], 'Fabrikanın atık suyundaki metil cıva besin zincirinde birikti; bu balıkları yiyen insanlarda ağır sinir sistemi hastalıkları görüldü.'),
  ('1991 Körfez Savaşı sırasında Kuveyt\'te yaşanan büyük çevre felaketi hangisidir?', 'Yüzlerce petrol kuyusunun ateşe verilmesi', ['Bir nükleer santralin patlaması', 'Büyük bir barajın yıkılması', 'Aral Gölü\'nün birkaç yılda kurutulması'], 'Geri çekilen Irak kuvvetleri yüzlerce petrol kuyusunu ateşe verdi; yangınların söndürülmesi aylar sürdü ve büyük hava ve toprak kirliliğine neden oldu.'),
  ('Okyanuslarda aşırı avlanmayı azaltmak için aşağıdaki önlemlerden hangisi en doğrudan etkiyi yapar?', 'Bilimsel verilere dayanan av kotaları belirlemek', ['Balıkçı teknelerinin motor gücünü artırmak', 'Ağ gözlerini daha da küçültmek', 'Av sezonunu yıl boyuna yaymak'], 'Stok tahminlerine göre belirlenen toplam av kotaları, balık nüfusunun kendini yenileyebileceği düzeyde av yapılmasını sağlar; küçük ağ gözleri ise yavru balıkları da yakalayarak sorunu büyütür.'),
  ('Bir maden şirketi tropikal bir ülkede yeni bir açık ocak açmak istiyor; yatak bir akarsuyun yukarı havzasında, köylerin içme suyu kaynağına yakın. Bu projenin değerlendirmesinde öncelikle hangi çalışma yapılmalıdır?', 'Çevresel etki değerlendirmesi', ['Turizm tanıtım kampanyası', 'Yöredeki turizm potansiyelini tanıtan bir reklam kampanyası', 'Maden ürününün reklamı'], 'ÇED, projenin su, toprak, biyoçeşitlilik ve yerel halk üzerindeki etkilerini önceden inceleyerek önlemleri ya da projenin uygun olup olmadığını belirler.'),
  ('Bir ülkede yeni bir çay plantasyonu kurulacaktır. Aşağıdaki alanlardan hangisi en uygundur?', 'Bol yağış alan, asitli topraklı, eğimli ılıman tropik yamaçlar', ['Kireçli topraklı, yazları kurak ve sıcak geçen, sulanmayan bir Akdeniz kıyı ovası', 'Sert kışlı ve kısa yazlı bir bozkır', 'Yıllık yağışı 100 mm\'nin altında olan bir çöl'], 'Çay bol ve düzenli yağış, asitli toprak ve suyun birikmediği eğimli araziler ister; Darjeeling, Sri Lanka yaylaları ve Kenya yaylaları bu koşulları sağlar.'),
  ('Bir ülke yeni bir petrol rafinerisi kurmak istemektedir. Ülkenin kendi petrolü yoktur ve petrolü tankerlerle ithal etmektedir. En uygun yer neresidir?', 'Derin sulu bir limana sahip, büyük tüketim merkezine yakın kıyı', ['Denizden 1.000 km uzaktaki bir dağ köyü', 'Hiç yolu olmayan bir ada', 'Tarım arazileriyle çevrili, demiryolu ve boru hattı bağlantısı olmayan bir iç ova'], 'İthal ham petrol tankerlerle geldiği için limanda kurulan rafineri aktarma maliyetinden kurtulur; ürünlerin tüketim merkezine yakın olması dağıtımı ucuzlatır.'),
  ('Bir ülke, konteyner gemilerinin büyüklüğü arttığı için limanının bundan sonra ana rotalardan çıkarılacağından endişe etmektedir. Aşağıdaki önlemlerden hangisi bu sorunu en doğrudan çözer?', 'Limanın su derinliğini ve rıhtım uzunluğunu artırmak', ['Liman çevresine yeni otoparklar ve alışveriş merkezleri yapmak', 'Limanda balık pazarı açmak', 'Limanın işletme saatlerini kısaltmak'], 'Büyük gemilerin yanaşabilmesi için derin su, uzun rıhtım ve büyük vinçler gerekir; tarama ve yeni terminal yatırımları bu nedenle yapılır.'),
  ('Kömür, petrol ve doğal gazın ‘fosil yakıt’ olarak adlandırılmasının nedeni nedir?', 'Milyonlarca yıl önce yaşamış canlıların kalıntılarından oluşmaları', ['Yalnız fosillerin bulunduğu müzelerde saklanmaları', 'Yer kabuğunun derinliklerinde magmanın soğuyup kristalleşmesiyle oluşmaları', 'Laboratuvarda yapay olarak üretilmeleri'], 'Fosil yakıtlar eski bitki ve deniz canlılarının gömülüp ısı ve basınçla dönüşmesiyle oluşur; oluşumları çok uzun sürdüğünden insan ölçeğinde yenilenemezler.'),
  ('Aşağıdaki ürünlerden hangisi ılıman kuşakta açık alanda yetiştirilemez?', 'Kakao', ['Buğday', 'Şeker pancarı', 'Elma'], 'Kakao sürekli sıcak ve nemli ekvatoral koşullar ister; buğday, şeker pancarı ve elma ise ılıman kuşağın ürünleridir.'),
  ('Aşağıdaki ürün gruplarından hangisinin tamamı tropikal kuşakta yetişir?', 'Muz, kakao, doğal kauçuk', ['Çavdar, yulaf, şeker pancarı', 'Zeytin, üzüm, incir', 'Buğday, arpa, keten'], 'Muz, kakao ve kauçuk ağacı yüksek sıcaklık ve nem ister; diğer gruplardaki ürünler ılıman ya da Akdeniz iklim bölgelerinde yetişir.'),
  ('Kesme çiçek, ilaç ve akıllı telefon gibi ürünlerin uluslararası ticarette sıklıkla hava yoluyla taşınmasının nedeni nedir?', 'Hafif, değerli ya da çabuk bozulan ürünler olmaları', ['Hava yolunun ton başına en ucuz taşıma türü olması ve büyük hacim sunması', 'Bu ürünlerin gemiyle taşınmasının yasak olması', 'Uçakların en çok yük taşıyan araç olması'], 'Hava taşımacılığı pahalı ama hızlıdır; birim ağırlık başına değeri yüksek ya da tazeliğini çabuk yitiren ürünler için tercih edilir.'),
  ('Uluslararası ticarette taşınan malların hacimce büyük bölümü hangi taşıma türüyle taşınır?', 'Deniz yolu', ['Hava yolu', 'Karayolu', 'Demiryolu'], 'Dünya ticaretindeki yüklerin hacimce yaklaşık yüzde 80\'den fazlası gemilerle taşınır; deniz yolu büyük hacimli yükleri uzak mesafelere en ucuz biçimde taşır.'),
  ('Petrolün dünya ekonomisindeki büyük önemi nedeniyle ona halk arasında verilen ad hangisidir?', 'Kara altın', ['Beyaz altın', 'Yeşil altın', 'Mavi altın'], 'Petrol koyu rengi ve ekonomik değeri nedeniyle ‘kara altın’ olarak anılır; ‘beyaz altın’ ise pamuk ya da tuz için, ‘mavi altın’ su için kullanılır.'),
  ('Kimyasal gübre ve sentetik tarım ilacı kullanmadan, doğal yöntemlerle yapılan ve ürünlerinin sertifikayla satıldığı tarım türüne ne ad verilir?', 'Organik tarım', ['Entansif tarım', 'Monokültür', 'Plantasyon tarımı'], 'Organik tarımda hayvan gübresi, kompost, ekim nöbeti ve biyolojik mücadele kullanılır; ürünler denetim ve sertifikayla pazarlanır.'),
  ('Trol avcılığına yöneltilen başlıca çevresel eleştiri nedir?', 'Ağların deniz tabanında sürüklenerek tabandaki canlıların yaşam alanını tahrip etmesi', ['Yalnız yüzeydeki balıkları yakalaması', 'Hiç balık yakalayamaması', 'Balıkçılara çok az iş sağlaması'], 'Dip trolleri ağır ağları tabanda sürükler; mercanları, deniz çayırlarını ve tabandaki canlıları yok eder, hedef dışı türleri de yakalar.'),
  ('Tarım ürünlerinin dünyadaki yetişme alanlarını en çok belirleyen doğal etmen hangisidir?', 'İklim', ['Nüfus yoğunluğu', 'Pazar uzaklığı', 'Sermaye miktarı'], 'Her bitkinin sıcaklık, yağış ve vejetasyon süresi istekleri farklıdır; bu nedenle ürünlerin doğal yayılış alanlarını öncelikle iklim belirler.'),
  ('Basra Körfezi çevresindeki ülkelerin ekonomilerinin büyük ölçüde dayandığı kaynak hangisidir?', 'Petrol ve doğal gaz', ['Kahve ve kakao', 'Orman ürünleri ve balıkçılık', 'Pamuk ve yün'], 'Suudi Arabistan, Kuveyt, Katar ve BAE gibi ülkelerin ihracat ve kamu gelirlerinin büyük bölümü petrol ve doğal gazdan gelir.'),
  ('Güneş panellerinin ışığı doğrudan elektriğe dönüştürmesini sağlayan teknolojiye ne ad verilir?', 'Fotovoltaik', ['Jeotermal', 'Hidrolik', 'Termik'], 'Fotovoltaik hücrelerde silisyum gibi yarı iletkenler güneş ışığını soğurarak doğrudan elektrik akımı üretir.'),
  ('Rüzgâr türbinleri hangi enerji dönüşümünü gerçekleştirir?', 'Hareket enerjisini elektrik enerjisine', ['Kimyasal enerjiyi ısı enerjisine', 'Nükleer enerjiyi ışık enerjisine', 'Elektrik enerjisini hareket enerjisine'], 'Rüzgâr kanatları döndürür; kanatların dönme hareketi jeneratörde elektriğe çevrilir.'),
  ('Sibirya\'nın zengin petrol, gaz ve maden kaynaklarının işletilmesini zorlaştıran başlıca etkenler hangi seçenekte birlikte verilmiştir?', 'Çok sert iklim, permafrost ve pazarlara uzaklık', ['Aşırı sıcak ve tropikal yağışlar', 'Kalabalık nüfus ve dar alan', 'Kıyı ovalarının çok geniş olması ve tropikal hastalıkların yaygınlığı'], 'Uzun ve çok soğuk kışlar, yazın çözülen bataklık zemin ve tüketim merkezlerine binlerce kilometre uzaklık, Sibirya\'da yatırım ve taşıma maliyetlerini artırır.'),
  ('Japonya\'nın enerji kaynaklarının ve besin maddelerinin önemli bir bölümünü ithal etmek zorunda olmasının coğrafi nedeni nedir?', 'Dağlık yapısı nedeniyle tarım arazisinin ve yeraltı kaynaklarının sınırlı olması', ['Ülkenin çok seyrek nüfuslu olması', 'Japonya\'nın denize kıyısının olmaması', 'Ülkenin tamamen çöllerle kaplı olması'], 'Japonya\'nın topraklarının büyük bölümü dağlıktır; kalabalık nüfusa karşın tarım arazisi azdır, petrol, gaz ve demir cevheri gibi kaynakları da yok denecek kadar azdır.'),
  ('Bir çiftçinin 45 dekar tarlası vardır. Bu tarla kaç hektardır? (1 hektar = 10 dekar)', '4,5', ['450', '45', '0,45'], '1 hektar 10 dekar olduğundan 45 / 10 = 4,5 hektardır.'),
  ('Bir ülkenin yıllık elektrik tüketimi 300 milyar kWh, nüfusu 60 milyondur. Kişi başına yıllık elektrik tüketimi kaç kWh\'tir?', '5.000', ['500', '50.000', '18.000'], '300.000.000.000 / 60.000.000 = 5.000 kWh\'tir.'),
  ('Bir ülkede bir yılda üretilen 250 milyar kWh elektriğin 75 milyar kWh\'i hidroelektrik santrallerinden gelmiştir. Hidroelektriğin payı yüzde kaçtır?', '30', ['25', '75', '33,3'], '75 / 250 × 100 = %30.'),
  ('Bir ülke günde 2 milyon varil petrol ihraç etmektedir. Varil fiyatı 80 dolar ise günlük ihracat geliri kaç milyon dolardır?', '160', ['40', '82', '1.600'], '2.000.000 × 80 = 160.000.000 dolar, yani 160 milyon dolardır.'),
  ('Bir rüzgâr santralinde her birinin kurulu gücü 3 MW olan 50 türbin bulunmaktadır. Santralin toplam kurulu gücü kaç MW’tır?', '150', ['53', '15', '1.500'], 'Toplam kurulu güç = türbin sayısı × türbin gücü = 50 × 3 = 150 MW’tır. Gerçek üretim, rüzgâr koşullarına bağlı kapasite faktörüyle bunun altında kalır.'),
  ('Bir ülkenin enerji arz güvenliğini artırmak için aşağıdaki stratejilerden hangisi en uygundur?', 'Enerji kaynaklarını ve tedarikçi ülkeleri çeşitlendirmek', ['Bütün enerjiyi tek bir ülkeden almak', 'Ülkenin bütün enerji ithalatını tek bir boru hattı ve tek bir tedarikçi ülke üzerinden yapmak', 'Yerli kaynakları hiç kullanmamak'], 'Farklı kaynaklar (yenilenebilir, gaz, nükleer vb.) ve farklı tedarikçiler, birinde yaşanan kesintinin etkisini azaltır.'),
  ('Bir ülkede rüzgâr potansiyeli yüksek, güneşlenme süresi kısa, kömür ve petrol kaynakları yoktur. Bu ülkenin yerli enerji üretimini artırmak için en mantıklı öncelik hangisidir?', 'Kıyı ve açık deniz rüzgâr santrallerine yatırım yapmak', ['Güneşlenme süresi kısa olmasına karşın geniş alanlara büyük güneş tarlaları kurmak', 'Kömür madeni açmak', 'Petrol rafinerisi kurup yerli petrol işlemek'], 'Ülkenin elinde bol olan yerli kaynak rüzgârdır; diğer seçenekler ya düşük verimli ya da ülkede bulunmayan kaynaklara dayanır.'),
  ('Kahve ihracatına bağımlı bir ülkede dünya kahve fiyatları bir yılda yarı yarıya düşmüştür. Bu durumun en doğrudan sonucu hangisidir?', 'Ülkenin döviz gelirlerinin ve üretici gelirlerinin ciddi biçimde azalması', ['Ülkede kahve tüketiminin yasaklanması', 'Ülkenin kahveyi daha pahalıya satabilmesi', 'Kahve üretiminin kendiliğinden ikiye katlanması'], 'Tek ürüne bağımlı ekonomilerde fiyat düşüşü doğrudan ihracat gelirine ve çiftçi gelirine yansır; bu da ithalat kapasitesini ve kamu gelirlerini azaltır.'),
  ('Bir ada ülkesinin tek gelir kaynağı turizmdir. Ülkenin ekonomik kırılganlığını azaltmak için aşağıdakilerden hangisi en uygun öneridir?', 'Balıkçılık, yenilenebilir enerji ve dijital hizmetlerle ekonomiyi çeşitlendirmek', ['Turizm dışındaki bütün sektörleri kapatmak', 'Turist sayısını tamamen sınırsız artırmak', 'Tüm gıdayı tek bir ülkeden almak'], 'Tek sektöre bağımlılık, salgın ya da doğal afet gibi şoklarda gelirin çökmesine yol açar; ekonomik çeşitlendirme bu riski dağıtır.'),
  ('İki ülke karşılaştırılıyor: A ülkesi elektriğinin %80\'ini kömürden, B ülkesi %80\'ini hidroelektrik ve nükleerden üretiyor. Birim elektrik başına karbon salımı için hangisi doğrudur?', 'B\'nin salımı A\'nınkinden çok daha düşüktür', ['A\'nın salımı B\'ninkinden çok daha düşüktür', 'İkisinin salımı eşittir', 'B\'nin salımı daha yüksektir çünkü nükleer kömür yakar'], 'Hidroelektrik ve nükleer santraller elektrik üretirken neredeyse hiç CO₂ salmaz; kömür ise birim elektrik başına en çok CO₂ salan kaynaktır.'),
  ('Bir bölgede altın madeni açılması planlanmaktadır. Aşağıdakilerden hangisi madenin bölgeye olası olumlu etkisi değil, olumsuz etkisidir?', 'Siyanürlü atıkların su kaynaklarını kirletme riski', ['Yerel istihdamın artması', 'Bölgeye yol, elektrik ve su gibi altyapı yatırımlarının gelmesi', 'Vergi ve kira gelirlerinin artması'], 'İstihdam, altyapı ve vergi geliri madenciliğin olası yararlarıdır; atık barajları ve kimyasal kirlenme ise başlıca çevresel risklerdir.'),
  ('Dünyada en çok tüketilen birincil enerji kaynakları sıralamasında uzun süredir ilk sırada yer alan kaynak hangisidir?', 'Petrol', ['Rüzgâr', 'Jeotermal', 'Gelgit'], 'Petrol, özellikle ulaşımdaki ağırlığıyla onlarca yıldır küresel birincil enerji tüketiminde birinci sıradadır; onu kömür ve doğal gaz izler.'),
  ('Bir ülkenin dört tarım ürünü için üretim ve tüketim verileri (milyon ton) şöyledir: Buğday 20/25, Pirinç 8/6, Mısır 10/12, Arpa 5/7. Bu ülke hangi üründe net ihracatçı olabilir?', 'Yalnız pirinçte', ['Yalnız buğdayda', 'Mısır ve arpada', 'Buğday ve pirinçte'], 'Yalnız pirinçte üretim (8) tüketimden (6) fazladır; diğer ürünlerde tüketim üretimi aşar ve ülke ithalatçıdır.'),
  ('Bir yük 1.200 km uzağa taşınacaktır. Yük 500 ton ağırlığında, hacimli ve aceleye gelmeyen bir maden cevheridir; güzergâh boyunca hem raylı sistem hem de kara yolu bağlantısı bulunmaktadır. En uygun taşıma türü hangisidir?', 'Demiryolu', ['Hava yolu', 'Karayolu', 'Kurye hizmeti'], 'Ağır, hacimli ve zamana duyarlı olmayan yüklerin uzun mesafede taşınmasında demiryolu ton başına maliyeti en düşük kara taşıma türüdür.'),
  ('Bir hükümet kırsal kesimde yeni bir kâğıt fabrikası kurmayı planlıyor. Kâğıt üretimi bol odun ve çok su gerektiriyor. Aşağıdaki yerlerden hangisi en uygundur?', 'Geniş iğne yapraklı ormanların yakınında, büyük bir akarsu kıyısında', ['Çölün ortasında, kum tepelerinin yanında', 'Tundra kuşağında, ağaçsız ve sürekli donmuş bir düzlükte', 'Kentin ortasında, su kaynaklarından uzakta'], 'Kâğıt hamuru sanayisi hem ham madde (odun) hem de üretim için çok su ister; bu nedenle orman bölgelerinde, akarsu ya da göl kıyılarında kurulur.'),
  ('Bir ülkenin balık tüketimi artarken doğal stoklar azalmaktadır. Aşağıdaki politikalardan hangisi hem arzı artırır hem de doğal stoklar üzerindeki baskıyı azaltır?', 'Sürdürülebilir akuakültürü desteklemek', ['Av yasağı dönemlerini kaldırmak', 'Daha küçük gözlü ağlara izin vermek', 'Daha büyük ve güçlü trol filoları satın alıp açık denize göndermek'], 'Kontrollü yetiştiricilik doğal stoklara dokunmadan balık arzı sağlar; diğer seçenekler aşırı avlanmayı artırır.'),
  ('İsrail ve Körfez ülkeleri gibi kurak ülkelerde deniz suyunun tuzdan arındırılarak (desalinasyon) içme ve sulama suyu elde edilmesinin en önemli dezavantajı hangisidir?', 'Çok enerji gerektirdiği için maliyetinin yüksek olması', ['Elde edilen suyun içilemeyecek kadar tuzlu kalması', 'Bu yöntemin yalnız tatlı su göllerinde uygulanabilmesi', 'Tesislerin deniz kıyısında kurulamaması'], 'Ters ozmoz ya da damıtma ile tuzun ayrılması büyük miktarda enerji ister; ayrıca geriye kalan çok tuzlu atık su (salamura) denize verildiğinde kıyı ekosistemlerini etkileyebilir.'),
  ('Bir ülke petrol ihracatından elde ettiği gelirin bir bölümünü eğitim, altyapı ve petrol dışı sanayilere yatırmaktadır. Bu politika en çok hangi sorunu önlemeye yöneliktir?', 'Petrol tükendiğinde ya da fiyatı düştüğünde ekonominin çökmesi', ['Petrol fiyatlarının artması', 'Dünya petrol fiyatlarının sürekli artıp gelirin kontrolsüz büyümesi', 'Nüfusun eğitim düzeyinin yükselmesi'], 'Kaynak gelirini çeşitlendirmede kullanmak, tek ürüne bağımlılığın yarattığı kırılganlığı azaltır ve tükenme sonrasına hazırlık sağlar.'),
  ('Bir ülkenin bütün elektriğini yenilenebilir kaynaklardan üretmesine en yakın örneklerden biri olan İzlanda\'nın elektrik kaynakları hangi seçenekte doğru verilmiştir?', 'Hidroelektrik ve jeotermal', ['Kömür ve petrol', 'Nükleer ve doğal gaz', 'Güneş ve gelgit santralleri'], 'İzlanda elektriğinin neredeyse tamamını buzul nehirlerinden beslenen hidroelektrik santralleri ile volkanik alanlardaki jeotermal santrallerden elde eder.'),
  ('Avustralya\'nın önemli ihraç ürünleri arasında demir cevheri, kömür ve LNG\'nin yer alması ülke ekonomisinin hangi özelliğini gösterir?', 'Doğal kaynak ihracatına dayalı bir yapıya sahip olduğunu', ['Ekonomisinin yalnız finans ve turizm gibi hizmet sektörlerine dayandığını', 'Hiç doğal kaynağı bulunmadığını', 'Ham madde ithalatçısı olduğunu'], 'Avustralya gelişmiş bir ülke olmasına karşın ihracatında maden ve enerji ürünleri ağır basar; başlıca müşterileri Asya ülkeleridir.'),
  ('Bir ülkenin aldığı malların ve hizmetlerin toplamına ithalat denir. Bir ülkenin başka ülkelere sattığı mallara ne ad verilir?', 'İhracat', ['Transit', 'Kabotaj', 'Gümrük'], 'İhracat yurt dışına yapılan satışlardır; ithalat ise yurt dışından yapılan alımlardır.'),
  ('Et, süt ürünleri, aşı ve taze meyve gibi çabuk bozulan ürünlerin üretim yerinden tüketiciye kadar kesintisiz soğutularak taşınıp depolanmasını sağlayan sisteme ne ad verilir?', 'Soğuk zincir', ['Kombine taşımacılık', 'Transit ticaret', 'Kabotaj sistemi'], 'Soğuk zincir soğutmalı depo, kamyon, konteyner ve gemilerden oluşur; zincirin bir halkasında kopma ürünün bozulmasına yol açar.'),
  ('Aşağıdakilerden hangisi madenciliğin bulunduğu bir yöreye getirebileceği ekonomik yararlardan biridir?', 'Yeni iş olanaklarının ortaya çıkması', ['Tarım arazilerinin genişlemesi', 'Akarsuların temizlenmesi', 'Ormanların büyümesi'], 'Maden işletmeleri çalışan, yan hizmetler ve ulaşım ihtiyacı yaratarak yöreye istihdam ve gelir sağlar; buna karşılık çevresel bedelleri de vardır.'),
  ('Kıyıdan uzak, deniz tabanından petrol ve doğal gaz çıkarılan yapılara ne ad verilir?', 'Açık deniz platformu', ['Rafineri', 'Gaz sayacı', 'Tanker terminali'], 'Açık deniz platformları kıta sahanlığı üzerinde, deniz tabanına sabitlenmiş ya da yüzen yapılar olarak kurulur; Kuzey Denizi ve Meksika Körfezi bilinen örneklerdir.'),
  ('Hidroelektrik santralleri için aşağıdaki akarsulardan hangisi daha elverişlidir?', 'Dağlık bir bölgede bol sulu ve eğimi fazla olan akarsu', ['Düz bir ovada yavaş akan ve az sulu akarsu', 'Yazın tamamen kuruyan çöl deresi', 'Deltada çok kollara ayrılmış akarsu'], 'Elektrik üretimi düşü yüksekliği ve akımla artar; eğimli ve bol sulu akarsular bu nedenle en elverişlidir.'),
  ('Güneş enerjisi santrallerinin geniş alanlarda kurulması için en uygun arazi hangisidir?', 'Tarıma elverişsiz, düz ve güneşli kurak araziler', ['Verimli ve sulanan tarım ovaları', 'Sık ormanlarla kaplı yamaçlar', 'Sürekli sisli kıyı bataklıkları'], 'Güneş tarlaları için güneşlenmesi bol, düz ve başka ekonomik kullanımı az olan araziler seçilir; böylece tarım ve orman alanları korunur.'),
  ('Bir limana gemiyle gelen buğdayın yakınındaki un fabrikasında işlenip un olarak iç bölgelere gönderilmesi aşağıdaki kavramlardan hangisiyle en iyi açıklanır?', 'Limanların ithal ham maddeyi işleyen sanayiler için uygun olması', ['Fabrikaların her zaman dağlık alanlara kurulması', 'Buğdayın yalnız denizde yetişmesi', 'Unun gemiyle taşınamaması'], 'Ham madde limanda zaten gemiden indirildiği için orada işlenmesi ek aktarma maliyetini ortadan kaldırır.'),
  ('Ekvator çevresindeki ülkelerin çoğunun kahve, kakao ve muz ihraç edip buğday ithal etmesinin temel nedeni hangisidir?', 'İklimin tropikal ürünlere uygun olup buğday için elverişsiz olması', ['Bu ülkelerde hiç tarım arazisi bulunmaması', 'Buğdayın tropikal ülkelerde yasak olması', 'Bu ülkelerde hiç ekmek tüketilmemesi'], 'Buğday ılıman iklim tahılıdır; sıcak ve nemli ekvatoral iklimde iyi yetişmez. Bu ülkeler karşılaştırmalı üstünlüğe sahip oldukları tropikal ürünleri ihraç eder.'),
  ('Bir ülke dış pazarlardan büyük miktarda petrol almaktadır. Bu ülkenin elektrikli toplu taşımaya ve yenilenebilir enerjiye yatırım yapmasının ekonomik yararı nedir?', 'Enerji ithalatına ödenen dövizin azalması', ['Petrol fiyatlarının dünyada hemen sıfırlanması', 'Ülkenin petrol ihracatçısı olması', 'Ülkedeki bütün sanayinin kapanması'], 'İthal petrole bağımlılık azaldığında dış ticaret açığı küçülür ve fiyat şoklarına karşı kırılganlık azalır.'),
  ('Aşağıdakilerden hangisi tarımda makineleşmenin sonuçlarından biridir?', 'Tarımda çalışan kişi sayısının azalması', ['Tarımsal verimin her yerde düşmesi', 'Tarım alanlarının yok olması', 'Hasat süresinin uzaması'], 'Makineler birçok işi kısa sürede yapar; bu da tarımda gerekli işgücünü azaltır ve kırsaldan kente göçü hızlandırabilir.'),
  ('Bir kentte kurulan büyük bir otomobil fabrikasının çevresinde zamanla lastik, cam, koltuk ve elektronik parça üreten fabrikaların da açılması hangi kavramla açıklanır?', 'Yan sanayinin ana sanayi çevresinde kümelenmesi', ['Sanayisizleşme', 'Kırsallaşma', 'Monokültür'], 'Ana sanayi büyük ve sürekli talep yaratır; tedarikçiler taşıma ve iletişim kolaylığı için ona yakın kurulur. Bu, yığılma ekonomilerinin tipik bir örneğidir.'),
];
